import React, { useState } from 'react';

const styles = {
  cover: {
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    background: '#fff',
    position: 'relative',
    overflow: 'hidden',
  },
  names: {
    display: 'flex',
    width: '100%',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '0 60px',
    position: 'absolute',
    top: '50%',
    transform: 'translateY(-50%)',
    zIndex: 2,
    pointerEvents: 'none',
  },
  nameTxt: {
    fontFamily: "'Dancing Script', cursive",
    fontSize: '3.5rem',
    color: '#222',
    animation: 'fadeIn 1.5s ease forwards',
  },
  doorWrapper: {
    position: 'relative',
    width: '320px',
    height: '520px',
    zIndex: 3,
    cursor: 'pointer',
    perspective: '1000px',
  },
  doorContainer: {
    width: '100%',
    height: '100%',
    position: 'relative',
  },
  doorImgLeft: {
    position: 'absolute',
    left: 0,
    top: 0,
    width: '50%',
    height: '100%',
    objectFit: 'cover',
    transformOrigin: 'left center',
    transition: 'transform 1.2s cubic-bezier(0.4, 0, 0.2, 1)',
    zIndex: 4,
  },
  doorImgRight: {
    position: 'absolute',
    right: 0,
    top: 0,
    width: '50%',
    height: '100%',
    objectFit: 'cover',
    transformOrigin: 'right center',
